ize:53px;letter-spacing:-3px;margin:24px 0}.lead{font-size:12px;max-width:360px}.trust{margin-top:22px;gap:12px;font-size:9px}.auth-card{padding:25px}.features{grid-template-columns:1fr;margin:0 22px}.feature,.feature:first-child{padding:24px 0;border-right:0;border-bottom:1px solid var(--line)}footer{font-size:9px;line-height:1.8;flex-wrap:wrap}.portal{padding:30px 20px}.portal-title{align-items:start;flex-direction:column}.portal-title h1{font-size:35px}.workspace{grid-template-columns:1fr}.vehicles{display:flex;gap:10px;overflow:auto}.vehicle-button{min-width:190px}.panel{padding:22px}.status-labels{font-size:8px}.features h3{font-size:15px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}@media print{body{background:white;color:black}header,.env,footer,#public-view,.workspace>aside,.portal-title button,.expiry{display:none!important}.portal{padding:0}.workspace,.two-col{display:block}.panel{background:white;color:black;border:1px solid #bbb;break-inside:avoid}.panel p,.details small,.invoice,.serial,.money-row,.activity,.remaining,.warranty code{color:black!important}.tag{color:black;border-color:#777}}
